// Cache hit : on parse le JSON stocké et on renvoie le contrat
const record = $input.first().json;

let cached;
try {
  cached = JSON.parse(record.response_json);
} catch (e) {
  throw new Error('Cache JSON invalide pour key=' + record.cache_key + '. Détail : ' + e.message);
}

return [{
  json: {
    success: true,
    cached: true,
    generated_at: record.generated_at,
    diagnostic: cached.diagnostic
  }
}];

// Construit le payload Anthropic avec tool_use forcé
const machinesRaw = $('Airtable Search Machines').all();
const interventionsRaw = $('Airtable Search Interventions').all();

// Index machines par recId pour résoudre les liens dans Interventions
const machinesById = {};
machinesRaw.forEach(item => {
  const f = item.json;
  const recId = item.json.id || f.id;
  if (recId) {
    machinesById[recId] = {
      nom: f.Nom_machine || '?',
      type: f.Type || '?',
      localisation: f.Localisation || '?'
    };
  }
});

const today = new Date().toISOString().slice(0, 10);

// Format machines
const machinesLines = machinesRaw.map(item => {
  const f = item.json;
  const nbInter = Array.isArray(f.Interventions) ? f.Interventions.length : 0;
  return `- ${f.Nom_machine || '?'} | ${f.Type || '?'} | ${f.Localisation || '?'} | ${f.Etat || '?'} | Dernière maint : ${f.Derniere_maintenance || 'NA'} | Prochaine maint : ${f.Prochaine_maintenance_Preventive || 'NA'} | Garantie expire : ${f.Garantie_expiration || 'NA'} | Interventions totales : ${nbInter}`;
}).join('\n');

// Format interventions (filtre 60 jours, résout nom machine via index)
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 60);
const interventionsFiltered = interventionsRaw.filter(item => {
  const d = item.json.Date;
  return d && new Date(d) >= cutoff;
});

const interventionsLines = interventionsFiltered.map(item => {
  const f = item.json;
  const machineRecId = Array.isArray(f.Machine) && f.Machine.length > 0 ? f.Machine[0] : null;
  const machineNom = machineRecId && machinesById[machineRecId] ? machinesById[machineRecId].nom : '?';
  const dureeMin = f.Duree_min || 0;
  const dureeStr = dureeMin >= 60 ? `${(dureeMin / 60).toFixed(1)}h` : `${dureeMin}min`;
  const desc = (f.Description || '').slice(0, 80);
  return `- ${f.Date || '?'} | ${machineNom} | ${f.Type || '?'} | ${f.Type_panne || 'NA'} | Statut: ${f.Statut || '?'} | ${dureeStr} | ${desc}`;
}).join('\n');

// User message
const userMessage = `État du parc machine au ${today} :

MACHINES (${machinesRaw.length} unités)
${machinesLines}

INTERVENTIONS (60 derniers jours, ${interventionsFiltered.length} entrées)
${interventionsLines || '- aucune'}

Donne ton verdict en utilisant l'outil submit_diagnostic.`;

// System prompt
const systemPrompt = `Tu es chef d'atelier dans une PME industrielle de 50 personnes. Lundi matin, tu prends 90 secondes pour donner ton verdict sur le parc machine à ton DGS. Ton ton est lucide, sobre, factuel. Pas de superlatifs, pas de jargon corporate, pas de blabla. Tu parles vrai, comme un ancien qui a vu passer des pannes.

Tu reçois deux jeux de données : la liste des machines (état, secteur, dernière maintenance, prochaine maintenance préventive, garantie) et la liste des interventions des 60 derniers jours.

Règles de sortie :
- resume : 1 à 2 phrases, le verdict général du lundi matin
- alertes_critiques : machines en "Hors service" ou "Alerte", 1 ligne par machine, format "Nom (localisation) : motif court tiré des données"
- maintenances_a_prevoir : machines dont la prochaine maintenance préventive tombe dans les 30 jours, ou état "Maintenance prévue". Format : "Nom (localisation) : prévu le YYYY-MM-DD, point d'attention"
- patterns_par_secteur : 2 à 4 phrases qui interprètent un signal par localisation (Atelier 1 / Atelier 2 / Quai expédition / Stock). Pas de liste plate, tu interprètes : concentration de pannes, type récurrent, agent assigné, etc.
- Total : 5 à 8 phrases utiles cumulées. Pas de remplissage. Si rien à signaler dans une section, tu mets [] et tu ne te justifies pas.
- Aucune mention "selon les données fournies", "il semble que", "il pourrait être recommandé". Tu tranches.
- Réponse en français.

Tu réponds OBLIGATOIREMENT via l'outil submit_diagnostic, jamais en texte libre.`;

const tool = {
  name: 'submit_diagnostic',
  description: 'Soumet le diagnostic du parc machine au DGS',
  input_schema: {
    type: 'object',
    required: ['resume', 'alertes_critiques', 'maintenances_a_prevoir', 'patterns_par_secteur'],
    properties: {
      resume: { type: 'string', description: '1 à 2 phrases verdict général' },
      alertes_critiques: { type: 'array', items: { type: 'string' } },
      maintenances_a_prevoir: { type: 'array', items: { type: 'string' } },
      patterns_par_secteur: { type: 'array', items: { type: 'string' } }
    }
  }
};

return [{
  json: {
    anthropic_payload: {
      model: 'claude-haiku-4-5',
      max_tokens: 1000,
      temperature: 0.3,
      system: systemPrompt,
      tools: [tool],
      tool_choice: { type: 'tool', name: 'submit_diagnostic' },
      messages: [
        { role: 'user', content: userMessage }
      ]
    }
  }
}];

// Parse réponse Anthropic mode tool_use + filet regex de sécurité
const r = $input.first().json;

let diagnosticInput = null;

// Cas 1 (nominal) : tool_use forcé
if (Array.isArray(r.content)) {
  const toolBlock = r.content.find(b => b.type === 'tool_use' && b.name === 'submit_diagnostic');
  if (toolBlock && toolBlock.input) {
    diagnosticInput = toolBlock.input;
  }
}

// Cas 2 (filet de sécurité) : Claude n'a pas utilisé l'outil
if (!diagnosticInput && Array.isArray(r.content)) {
  const textBlock = r.content.find(b => b.type === 'text');
  if (textBlock && textBlock.text) {
    try {
      diagnosticInput = JSON.parse(textBlock.text);
    } catch (e) {
      const match = textBlock.text.match(/\{[\s\S]*\}/);
      if (match) {
        try { diagnosticInput = JSON.parse(match[0]); } catch (e2) {}
      }
    }
  }
}

if (!diagnosticInput) {
  throw new Error('Aucun diagnostic exploitable dans la réponse Anthropic. Raw : ' + JSON.stringify(r).slice(0, 500));
}

const now = new Date().toISOString();
const response = {
  success: true,
  cached: false,
  generated_at: now,
  diagnostic: {
    resume: diagnosticInput.resume || '',
    alertes_critiques: Array.isArray(diagnosticInput.alertes_critiques) ? diagnosticInput.alertes_critiques : [],
    maintenances_a_prevoir: Array.isArray(diagnosticInput.maintenances_a_prevoir) ? diagnosticInput.maintenances_a_prevoir : [],
    patterns_par_secteur: Array.isArray(diagnosticInput.patterns_par_secteur) ? diagnosticInput.patterns_par_secteur : []
  }
};

return [{
  json: {
    ...response,
    _cache_payload: {
      cache_key: 'diagnostic-parc-v1',
      endpoint: 'diagnostic',
      response_json: JSON.stringify(response),
      generated_at: now,
      ttl_hours: 720,
      notes: 'Auto-généré par workflow'
    }
  }
}];

// On reprend la réponse construite par Format Response
// et on enlève le _cache_payload avant de répondre au client
const src = $('Format Response').first().json;
const { _cache_payload, ...clean } = src;
return [{ json: clean }];
